<script setup lang="ts">import type {MaxFlow} from '../types/domain';import {number} from '../utils/format';defineProps<{flow:MaxFlow}>();</script><template><div class="table-scroll"><table><thead><tr><th>边ID / 方向</th><th>原/有效容量</th><th>流量</th><th>正/反残量</th><th>时长 / 分钟</th><th>证据</th></tr></thead><tbody><tr v-for="a in flow.arc_flows" :key="a.arc_id" :class="{disabled:a.disabled}"><td><b>{{a.arc_id}}</b><small>{{a.source}} → {{a.target}}</small></td><td>{{a.capacity}} / {{a.effective_capacity}}</td><td>{{a.flow}}</td><td>{{a.residual_forward}} / {{a.residual_reverse}}</td><td>{{number(a.travel_minutes)}}</td><td><span v-if="a.disabled" class="tag warning">停用</span><span v-if="flow.cut_arcs.some(c=>c.arc_id===a.arc_id)" class="tag cut">割边</span></td></tr></tbody></table></div></template>
